css:
.sec{position:relative; overflow:hidden}
.sec > *{position:relative; z-index:1}
/* 地紋として敷く（明度差3〜6%） */
.ghost{position:absolute; font:900 clamp(80px,18vw,210px)/.8 Helvetica,Arial,sans-serif; letter-spacing:-.02em; white-space:nowrap; color:#efe7d8; user-select:none; pointer-events:none; z-index:0}
.ghost.t{top:-120px; left:180px}
.ghost.b{bottom:-130px; left:-40px}
/* 主役のまま端で切る */
.bleed{font-size:clamp(56px,11vw,140px); font-weight:800; line-height:.82; letter-spacing:-.01em; color:#E8352B; white-space:nowrap; margin-left:6vw}
.wrap{overflow-x:clip}
